    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j][0] = grid[i][j]
                dp[i][j][1] = grid[i][j]
